class Solution:
    def maximumOr(self, nums: List[int], k: int) -> int:
        n = len(nums)
        left_or = [0] * n
        right_or = [0] * n
        result = 0

        # Calculate left OR for each index
        left = 0
        for i in range(n):
            left_or[i] = left | nums[i]
            left = left_or[i]

        # Calculate right OR for each index
        right = 0
        for i in range(n - 1, -1, -1):
            right_or[i] = right | nums[i]
            right = right_or[i]

        # Calculate the maximum OR value after applying the operation at most k times
        for i in range(n):
            if i == 0:
                result = max(result, right_or[i + 1])
            elif i == n - 1:
                result = max(result, left_or[i - 1])
            else:
                result = max(result, left_or[i - 1] | right_or[i + 1] | (nums[i] << k))

        return result

