class Solution:
    def maxNonDecreasingLength(self, nums1: List[int], nums2: List[int]) -> int:
        n = len(nums1)
        if n == 0:
            return 0

        # Initialize the length of the longest non-decreasing subarray
        max_length = 1
        # Initialize the current length of the non-decreasing subarray
        current_length = 1

        # Iterate through the arrays
        for i in range(1, n):
            # If nums1[i] is greater than or equal to nums1[i-1], we can extend the subarray
            if nums1[i] >= nums1[i-1]:
                current_length = max(current_length + 1, 1)
            else:
                current_length = 1

            # If nums2[i] is greater than or equal to nums1[i-1], we can extend the subarray
            if nums2[i] >= nums1[i-1]:
                current_length = max(current_length + 1, 1)
            else:
                current_length = 1

            # If nums2[i] is greater than or equal to nums2[i-1], we can extend the subarray
            if nums2[i] >= nums2[i-1]:
                current_length = max(current_length + 1, 1)
            else:
                current_length = 1

            # Update the maximum length of the non-decreasing subarray
            max_length = max(max_length, current_length)

        return max_length

