class Solution:
    def minAbsoluteDifference(self, nums: List[int], x: int) -> int:
        n = len(nums)
        min_diff = float('inf')

        for i in range(x, n):
            left = nums[i - x]
            index = bisect.bisect_left(nums[:i], left)
            if index < len(nums[:i]):
                min_diff = min(min_diff, abs(nums[i] - nums[:i][index]))
            if index > 0:
                min_diff = min(min_diff, abs(nums[i] - nums[:i][index - 1]))

        return min_diff

