class Solution:
    def minimumRightShifts(self, nums: List[int]) -> int:
        n = len(nums)
        count = 0

        for i in range(1, n):
            if nums[i] < nums[i - 1]:
                count += 1
                if count > 1:
                    return -1

        if count == 0:
            return 0

        if nums[-1] > nums[0]:
            return -1

        return n - count

