class Solution:
    def maximumSumOfHeights(self, maxHeights: List[int]) -> int:
        n = len(maxHeights)
        result = 0

        for i in range(n):
            left = [0] * n
            right = [0] * n

            # Calculate left pass
            stack = []
            for j in range(n):
                while stack and maxHeights[stack[-1]] > maxHeights[j]:
                    stack.pop()
                if stack:
                    left[j] = left[stack[-1]] + (j - stack[-1]) * maxHeights[stack[-1]]
                else:
                    left[j] = (j + 1) * maxHeights[j]
                stack.append(j)

            # Calculate right pass
            stack = []
            for j in range(n - 1, -1, -1):
                while stack and maxHeights[stack[-1]] > maxHeights[j]:
                    stack.pop()
                if stack:
                    right[j] = right[stack[-1]] + (stack[-1] - j) * maxHeights[stack[-1]]
                else:
                    right[j] = (n - j) * maxHeights[j]
                stack.append(j)

            # Calculate the sum for the current peak
            result = max(result, sum(left) + sum(right) - maxHeights[i])

        return result

