class Solution:
    def maxPartitionsAfterOperations(self, s: str, k: int) -> int:
        n = len(s)
        max_partitions = 0

        for i in range(n):
            count = Counter()
            partitions = 1
            for j in range(i, n):
                count[s[j]] += 1
                if len(count) > k:
                    partitions += 1
                    count = Counter(s[j+1:i+1])
                if j == n - 1:
                    partitions += 1
            max_partitions = max(max_partitions, partitions)

        return max_partitions

