class Solution:
    def minOperations(self, nums: List[int], k: int) -> int:
        xor_result = 0
        for num in nums:
            xor_result ^= num

        operations = 0
        for i in range(32):
            bit_k = (k >> i) & 1
            bit_xor = (xor_result >> i) & 1
            if bit_k != bit_xor:
                operations += 1

        return operations

