def is_infected(N, D, people):
    infected = [False] * N
    infected[0] = True

    for i in range(N):
        if infected[i]:
            for j in range(N):
                if i != j:
                    x1, y1 = people[i]
                    x2, y2 = people[j]
                    distance = math.sqrt((x1 - x2) ** 2 + (y1 - y2) ** 2)
                    if distance <= D:
                        infected[j] = True

    for i in range(N):
        if infected[i]:
            print("Yes")
        else:
            print("No")

