def transform_permutation(N, A):
    operations = []
    target = list(range(1, N + 1))

    for i in range(N):
        if A[i] != target[i]:
            for j in range(i + 1, N):
                if A[j] == target[i]:
                    operations.append((i + 1, j + 1))
                    A[i], A[j] = A[j], A[i]
                    break

    return len(operations), operations

