class Solution:
    def getSmallestString(self, s: str, k: int) -> str:
        result = list(s)

        for i in range(len(s)):
            if k == 0:
                break

            if s[i] == 'z':
                continue

            diff = ord('z') - ord(s[i])
            if k >= diff:
                result[i] = chr(ord(s[i]) + 1)
                k -= diff
            else:
                result[i] = chr(ord(s[i]) + k)
                k = 0

        return ''.join(result)

