class Solution:
    def minCostToEqualizeArray(self, nums: List[int], cost1: int, cost2: int) -> int:
        total_cost = 0
        min_cost = float('inf')

        # Find the median of the array
        nums.sort()
        median = nums[len(nums) // 2]

        # Calculate the cost to make all elements equal to the median
        for num in nums:
            total_cost += abs(num - median) * cost1

        # Calculate the cost to make all elements equal to the median using cost2
        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                total_cost += abs(nums[i] - nums[j]) * cost2

        # Return the minimum cost modulo 10^9 + 7
        return total_cost % (10**9 + 7)

