class Solution:
    def countOfPeaks(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums)
        peaks = []

        # Function to find all peaks in the array
        def find_peaks():
            for i in range(1, n - 1):
                if nums[i] > nums[i - 1] and nums[i] > nums[i + 1]:
                    peaks.append(i)

        # Initial peak finding
        find_peaks()

        # Result array to store the count of peaks for each query
        result = []

        # Process each query
        for query in queries:
            if query[0] == 1:
                l, r = query[1], query[2]
                # Count peaks in the subarray [l, r]
                count = 0
                for peak in peaks:
                    if l <= peak <= r:
                        count += 1
                result.append(count)
            elif query[0] == 2:
                index, val = query[1], query[2]
                # Update the value at the given index
                nums[index] = val
                # Re-find peaks after the update
                peaks = []
                find_peaks()

        return result

