class Solution:
    def numberOfAlternatingGroups(self, colors: List[int], queries: List[List[int]]) -> List[int]:
        n = len(colors)
        result = []
        alternating_groups = []

        # Initialize alternating groups
        for i in range(n):
            if i > 0 and colors[i] != colors[i - 1]:
                alternating_groups.append([i, i])
            else:
                if i > 0 and colors[i] == colors[i - 1]:
                    alternating_groups[-1][1] = i

        # Process queries
        for query in queries:
            if query[0] == 1:
                size = query[1]
                count = 0
                for group in alternating_groups:
                    if group[1] - group[0] + 1 == size:
                        count += 1
                result.append(count)
            elif query[0] == 2:
                index = query[1]
                color = query[2]
                if colors[index] != color:
                    colors[index] = color
                    # Update alternating groups
                    for i in range(n):
                        if i > 0 and colors[i] != colors[i - 1]:
                            alternating_groups.append([i, i])
                        else:
                            if i > 0 and colors[i] == colors[i - 1]:
                                alternating_groups[-1][1] = i

        return result

