def count_valid_operations(N: int, Q: int, P: List[int], V: List[int]) -> int:
    MOD = 998244353
    result = 0

    for i in range(1 << Q):
        valid = True
        current = [0] * N

        for j in range(Q):
            if (i >> j) & 1:
                start = P[j] - 1
                end = min(N, start + P[j])
                for k in range(start, end):
                    if current[k] > V[j]:
                        valid = False
                        break
                current[start:end] = [V[j]] * (end - start)

        if valid:
            result = (result + 1) % MOD

    return result

