class Solution:
    def canTraverseAllPairs(self, nums: List[int]) -> bool:
        if len(nums) == 1:
            return True

        # Dictionary to store the connected components
        graph = {}

        # Function to find the root of a node
        def find(x):
            if x not in graph:
                graph[x] = x
            if graph[x] != x:
                graph[x] = find(graph[x])
            return graph[x]

        # Function to union two nodes
        def union(x, y):
            rootX = find(x)
            rootY = find(y)
            if rootX != rootY:
                graph[rootX] = rootY

        # Iterate through each number in the array
        for num in nums:
            for i in range(2, int(math.sqrt(num)) + 1):
                if num % i == 0:
                    # Union the current number with its factors
                    union(num, i)
                    union(num, num // i)

        # Find the root of the first number
        root = find(nums[0])

        # Check if all numbers are connected to the root
        for num in nums:
            if find(num) != root:
                return False

        return True

