class Solution:
    def maximumSumQueries(self, nums1: List[int], nums2: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums1)
        pairs = [(nums1[i], nums2[i]) for i in range(n)]

        # Sort pairs by (nums1[i] + nums2[i]) in descending order
        pairs.sort(key=lambda x: -x[0] - x[1])

        # Stack to keep track of valid pairs
        stack = []

        # Result array to store the maximum sum for each query
        result = [-1] * len(queries)

        for i, (x, y) in enumerate(queries):
            while stack and stack[-1][0] >= x and stack[-1][1] >= y:
                _, sum_val = stack.pop()
                result[i] = max(result[i], sum_val)

            if result[i] == -1:
                for j in range(n):
                    if pairs[j][0] >= x and pairs[j][1] >= y:
                        stack.append((pairs[j][0], pairs[j][0] + pairs[j][1]))
                        result[i] = max(result[i], pairs[j][0] + pairs[j][1])
                        break

        return result

