            for i in range(1, len(path)):
                if path[i] % path[i-1] != 0 and path[i-1] % path[i] != 0:
                    return False
            return True

        def dfs(index, path):
            if index == n:
                if is_special_permutation(path):
                    return 1
                return 0
            count = 0
            for i in range(n):
                if not path or nums[i] % path[-1] == 0 or path[-1] % nums[i] == 0:
                    path.append(nums[i])
                    count += dfs(index + 1, path)
                    path.pop()
            return count

        return dfs(0, [])

