        n = len(s)

        @lru_cache(None)
        def is_semi_palindrome(sub):
            if len(sub) <= 1:
                return True
            mid = len(sub) // 2
            for i in range(mid):
                if sub[i] != sub[-i - 1]:
                    return False
            return True

        @lru_cache(None)
        def min_changes(start, remaining_parts):
            if remaining_parts == 1:
                return sum(1 for char in s[start:] if char != s[start])
            min_changes = float('inf')
            for end in range(start + 1, n - remaining_parts + 2):
                if is_semi_palindrome(s[start:end]):
                    min_changes = min(min_changes, min_changes(end, remaining_parts - 1))
                else:
                    min_changes = min(min_changes, min_changes(end, remaining_parts - 1) + 1)
            return min_changes

        return min_changes(0, k)

