class Solution:
    def constructProductMatrix(self, grid: List[List[int]]) -> List[List[int]]:
        n, m = len(grid), len(grid[0])
        result = [[0] * m for _ in range(n)]

        # Calculate the prefix product for each row
        prefix_product = [1] * n
        for i in range(n):
            for j in range(m):
                result[i][j] = prefix_product[i]
                prefix_product[i] *= grid[i][j]

        # Calculate the suffix product for each row
        suffix_product = [1] * n
        for i in range(n - 1, -1, -1):
            for j in range(m - 1, -1, -1):
                result[i][j] *= suffix_product[i]
                suffix_product[i] *= grid[i][j]

        # Apply modulo operation
        MOD = 12345
        for i in range(n):
            for j in range(m):
                result[i][j] %= MOD

        return result

