        n = len(s1)
        if s1 == s2:
            return 0

        # Count the number of positions where s1 and s2 differ
        diff_count = 0
        for i in range(n):
            if s1[i] != s2[i]:
                diff_count += 1

        # If the number of differing positions is odd, it's impossible to make them equal
        if diff_count % 2 != 0:
            return -1

        # Initialize the DP array
        dp = [float('inf')] * (diff_count // 2 + 1)
        dp[0] = 0

        # Fill the DP array
        for i in range(n):
            if s1[i] != s2[i]:
                for j in range(diff_count // 2, 0, -1):
                    dp[j] = min(dp[j], dp[j - 1] + x)
                dp[0] += 1

        return dp[-1]

