class Solution:
    def maximumSum(self, nums: List[int]) -> int:
        n = len(nums)
        max_sum = 0

        for i in range(1, 1 << n):
            subset = []
            for j in range(n):
                if i & (1 << j):
                    subset.append(nums[j])

            if self.is_complete(subset):
                max_sum = max(max_sum, sum(subset))

        return max_sum

    def is_complete(self, subset: List[int]) -> bool:
        for i in range(len(subset)):
            for j in range(i + 1, len(subset)):
                if not self.is_perfect_square(subset[i] * subset[j]):
                    return False
        return True

    def is_perfect_square(self, num: int) -> bool:
        root = int(num ** 0.5)
        return root * root == num

