class Solution:
    def minSizeSubarray(self, nums: List[int], target: int) -> int:
        n = len(nums)
        total_sum = sum(nums)
        full_cycles = target // total_sum
        remainder = target % total_sum

        if remainder == 0:
            return full_cycles * n

        min_length = float('inf')
        current_sum = 0
        left = 0

        for right in range(2 * n):
            current_sum += nums[right % n]

            while current_sum > remainder:
                current_sum -= nums[left % n]
                left += 1

            if current_sum == remainder:
                min_length = min(min_length, right - left + 1)

        if min_length == float('inf'):
            return -1

        return min_length + full_cycles * n

