            second_half = prefix_count[d + 1] - prefix_count[c]

            # Check if the characters in the first half and the second half can form a palindrome
            if (b - a + 1) % 2 == 0:
                if first_half == second_half:
                    result.append(True)
                else:
                    result.append(False)
            else:
                if first_half == second_half:
                    result.append(True)
                else:
