            while not is_palindrome(upper):
                upper += 1
            if abs(lower - num) <= abs(upper - num):
                return lower
            return upper

        closest_lower_palindrome = find_closest_palindrome(mid - 1)
        closest_upper_palindrome = find_closest_palindrome(mid + 1)

        cost_lower = cost_to_make_palindrome(closest_lower_palindrome)
        cost_upper = cost_to_make_palindrome(closest_upper_palindrome)

        return min(cost_lower, cost_upper)

