import heapq

class Solution:
    def minimumCost(self, source: str, target: str, original: List[str], changed: List[str], cost: List[int]) -> int:
        n = len(source)
        graph = [[] for _ in range(26)]

        # Build the graph
        for i in range(len(original)):
            u = ord(original[i]) - ord('a')
            v = ord(changed[i]) - ord('a')
            if cost[i] < float('inf'):
                graph[u].append((v, cost[i]))

        # Dijkstra's algorithm to find the minimum cost to convert each character
        def dijkstra(start):
            distances = [float('inf')] * 26
            distances[start] = 0
            pq = [(0, start)]
            while pq:
                dist, node = heapq.heappop(pq)
                for neighbor, weight in graph[node]:
                    if dist + weight < distances[neighbor]:
                        distances[neighbor] = dist + weight
                        heapq.heappush(pq, (dist + weight, neighbor))
            return distances

        # Calculate the total cost to convert source to target
        total_cost = 0
        for i in range(n):
            start = ord(source[i]) - ord('a')
            end = ord(target[i]) - ord('a')
            if start != end:
                distances = dijkstra(start)
                if distances[end] == float('inf'):
                    return -1
                total_cost += distances[end]

        return total_cost

