class Solution:
    def maxPalindromesAfterOperations(self, words: List[str]) -> int:
        char_count = {}
        total_chars = 0

        # Count the frequency of each character
        for word in words:
            for char in word:
                if char in char_count:
                    char_count[char] += 1
                else:
                    char_count[char] = 1
            total_chars += len(word)

        # Count the number of characters that appear an even number of times
        even_count = 0
        for count in char_count.values():
            if count % 2 == 0:
                even_count += count

        # Calculate the number of palindromes that can be formed
        words.sort(key=len)
        palindromes = 0
        for word in words:
            if total_chars % 2 == 0:
                if even_count >= len(word):
                    even_count -= len(word)
                    palindromes += 1
                else:
                    break
            else:
                if even_count >= len(word) - 1:
                    even_count -= (len(word) - 1)
                    palindromes += 1
                else:
                    break

        return palindromes

