def process_sequence(N, A):
    while True:
        found = False
        for i in range(N - 1):
            if abs(A[i] - A[i + 1]) != 1:
                if A[i] < A[i + 1]:
                    A = A[:i + 1] + [A[i] + 1] * (A[i + 1] - A[i]) + A[i + 1:]
                else:
                    A = A[:i + 1] + [A[i] - 1] * (A[i] - A[i + 1]) + A[i + 1:]
                found = True
                break
        if not found:
            break
    return A

