def bfs(grid, start, goal, T):
    H, W = len(grid), len(grid[0])
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    queue = deque([(start, 0, 0)])
    visited = set([start])

    while queue:
        (x, y), moves, candy_count = queue.popleft()

        if (x, y) == goal:
            return candy_count

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < H and 0 <= ny < W and grid[nx][ny] != '#' and (nx, ny) not in visited:
                if grid[nx][ny] == 'o':
                    visited.add((nx, ny))
                    queue.append(((nx, ny), moves + 1, candy_count + 1))
                else:
                    visited.add((nx, ny))
                    queue.append(((nx, ny), moves + 1, candy_count))

    return -1

