def find_stars(N, edges):
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    stars = []
    for i in range(1, N + 1):
        if len(graph[i]) == 1:
            stars.append(1)
            continue
        visited = [False] * (N + 1)
        stack = [i]
        while stack:
            node = stack.pop()
            if visited[node]:
                continue
            visited[node] = True
            for neighbor in graph[node]:
                if not visited[neighbor]:
                    stack.append(neighbor)
        if all(visited[j] for j in range(1, N + 1) if j != i):
            stars.append(1)
        else:
            stars.append(2)

    return sorted(stars)

