def process_string(S):
    stack = []
    result = []

    for char in S:
        if char == '(':
            stack.append(char)
        elif char == ')' and stack:
            while stack and stack[-1] != '(':
                result.append(stack.pop())
            if stack:
                stack.pop()  # Remove the '('
        else:
            result.append(char)

    return ''.join(result)

