def can_form_path(H, W, S):
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    start = (0, 0)
    end = (H - 1, W - 1)

    def is_valid(x, y):
        return 0 <= x < H and 0 <= y < W

    def dfs(x, y, path):
        if (x, y) == end:
            return path == ['s', 'n', 'u', 'k', 'e', 's', 'n', 'u']

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if is_valid(nx, ny):
                if S[nx][ny] == path[-1]:
                    if dfs(nx, ny, path + [S[nx][ny]]):
                        return True
        return False

    return dfs(start[0], start[1], [S[start[0]][start[1]]])

