import sys

def shift_outer_squares(grid):
    N = len(grid)
    outer_squares = []

    # Collect outer squares in clockwise order
    outer_squares.append(grid[0][0])  # (1,1)
    for i in range(1, N):
        outer_squares.append(grid[0][i])  # (1,2) to (1,N)
    for i in range(1, N):
        outer_squares.append(grid[i][N-1])  # (2,N) to (N,N)
    for i in range(N-2, 0, -1):
        outer_squares.append(grid[N-1][i])  # (N,1) to (N-2,1)

    # Shift outer squares clockwise
    shifted_squares = outer_squares[1:] + [outer_squares[0]]

    # Place shifted squares back into the grid
    index = 0
    for i in range(N):
        for j in range(N):
            if (i == 0 and j == 0) or (i == 0 and j == N-1) or (i == N-1 and j == 0) or (i == N-1 and j == N-1):
                grid[i][j] = shifted_squares[index]
                index += 1
            else:
                grid[i][j] = shifted_squares[index]
                index += 1

    return grid

