from itertools import combinations

def count_ways(N, T, M, incompatible_pairs):
    if M == 0:
        return 1 if T == 1 else 0

    # Convert pairs to sets for quick lookup
    pairs = set(tuple(pair) for pair in incompatible_pairs)

    # Helper function to check if a division is valid
    def is_valid_division(division):
        for a, b in pairs:
            if division[a-1] == division[b-1]:
                return False
        return True

    # Generate all possible divisions
    ways = 0
    for team in combinations(range(1, N+1), T):
        division = [0] * N
        for player in team:
            division[player-1] = 1
        if is_valid_division(division):
            ways += 1

    return ways

