def is_valid_parenthesis(s: str) -> bool:
    balance = 0
    for char in s:
        if char == '(':
            balance += 1
        elif char == ')':
            balance -= 1
        if balance < 0:
            return False
    return balance == 0

def count_valid_parentheses(S: str) -> int:
    MOD = 998244353
    n = len(S)
    count = 0

    for i in range(2 ** n):
        replacement = []
        for j in range(n):
            if S[j] == '?':
                replacement.append('(' if (i >> j) & 1 else ')')
            else:
                replacement.append(S[j])
        new_string = ''.join(replacement)
        if is_valid_parenthesis(new_string):
            count = (count + 1) % MOD

    return count

