from collections import defaultdict

def find_strongest_programmer(N, M, edges):
    graph = defaultdict(list)
    for A, B in edges:
        graph[A].append(B)

    def is_strongest(person):
        for other in range(1, N + 1):
            if other == person:
                continue
            if other not in graph[person]:
                return False
        return True

    strongest = -1
    for i in range(1, N + 1):
        if is_strongest(i):
            if strongest == -1:
                strongest = i
            else:
                return -1

    return strongest

