def expected_cost(N: int, M: int, costs: List[int], probabilities: List[List[int]], points: List[List[int]]) -> float:
    def expected_cost_recursive(wheel: int, remaining_points: int, total_cost: int) -> float:
        if remaining_points <= 0:
            return 0.0
        if wheel == N:
            return float('inf')

        min_cost = float('inf')
        for j in range(1, probabilities[wheel] + 1):
            cost = costs[wheel] + expected_cost_recursive(wheel + 1, remaining_points - points[wheel][j - 1], total_cost + costs[wheel])
            min_cost = min(min_cost, cost)

        return min_cost

    min_cost = float('inf')
    for j in range(1, probabilities[0] + 1):
        cost = costs[0] + expected_cost_recursive(1, M - points[0][j - 1], costs[0])
        min_cost = min(min_cost, cost)

    return min_cost

