def find_min_books_to_read(N, books):
    from collections import defaultdict
    graph = defaultdict(list)
    in_degree = [0] * (N + 1)

    for C_i, P in books:
        for j in range(C_i):
            graph[P[j]].append(i + 1)
            in_degree[i + 1] += 1

    queue = []
    for i in range(1, N + 1):
        if in_degree[i] == 0:
            queue.append(i)

    result = []
    while queue:
        book = queue.pop(0)
        result.append(book)
        for neighbor in graph[book]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    return result[1:]

