import math

def min_distance(N, checkpoints):
    if N == 2:
        return math.sqrt((checkpoints[1][0] - checkpoints[0][0]) ** 2 + (checkpoints[1][1] - checkpoints[0][1]) ** 2)

    min_s = float('inf')

    for i in range(1, N):
        for j in range(i + 1, N):
            for k in range(j + 1, N):
                for l in range(k + 1, N):
                    path = [0, i, j, k, l, N - 1]
                    distance = 0
                    for a in range(1, len(path)):
                        distance += math.sqrt((checkpoints[path[a]][0] - checkpoints[path[a - 1]][0]) ** 2 + (checkpoints[path[a]][1] - checkpoints[path[a - 1]][1]) ** 2)
                    penalty = 2 ** (len(path) - 2)
                    s = distance + penalty
                    min_s = min(min_s, s)

    return min_s

