def min_travel_time(N, A, B, C, D):
    # Initialize the distance matrix
    dist = [[float('inf')] * N for _ in range(N)]
    for i in range(N):
        dist[i][i] = 0

    # Fill the distance matrix with given distances
    for i in range(N):
        for j in range(N):
            dist[i][j] = D[i][j]

    # Floyd-Warshall algorithm to find the shortest paths
    for k in range(N):
        for i in range(N):
            for j in range(N):
                dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j])

    # Find the minimum time to travel from city 1 to city N
    min_time = float('inf')
    for i in range(N):
        min_time = min(min_time, dist[0][i] + dist[i][N-1])

    return min_time

