import sys

def can_transform(A, B):
    H, W = len(A), len(A[0])

    # Check if the grids are already identical
    if A == B:
        return 0

    # Check if it's possible to transform A to B
    for i in range(H):
        for j in range(W):
            if A[i][j] != B[i][j]:
                # Try to find a way to match the current cell
                for k in range(i, H):
                    if A[k][j] == B[i][j]:
                        # Swap rows to match the current cell
                        A[i], A[k] = A[k], A[i]
                        break
                else:
                    return -1

    # Check if the columns can be transformed
    for j in range(W):
        for i in range(H):
            if A[i][j] != B[i][j]:
                # Try to find a way to match the current cell
                for k in range(j, W):
                    if A[i][k] == B[i][j]:
                        # Swap columns to match the current cell
                        for l in range(i, H):
                            A[l][j], A[l][k] = A[l][k], A[l][j]
                        break
                else:
                    return -1

    return -1

