from collections import deque

def can_reach_goal(H, W, grid, medicines):
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    start = None
    goal = None

    for i in range(H):
        for j in range(W):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'T':
                goal = (i, j)

    if start is None or goal is None:
        return "No"

    queue = deque([(start, 0)])
    visited = set([start])

    while queue:
        (x, y), energy = queue.popleft()

        if (x, y) == goal:
            return "Yes"

        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if 0 <= nx < H and 0 <= ny < W and grid[nx][ny] != '#':
                if (nx, ny) not in visited:
                    visited.add((nx, ny))
                    queue.append(((nx, ny), energy))

    return "No"

