def min_expected_cost(N, A, X, Y):
    @lru_cache(None)
    def dp(n):
        if n == 0:
            return 0
        cost1 = X + dp(n // A)
        cost2 = Y + sum(dp(n // b) for b in range(1, 7)) / 6
        return min(cost1, cost2)

    return dp(N)

