def find(parent, x):
    if parent[x] != x:
        parent[x] = find(parent, parent[x])
    return parent[x]

def union(parent, x, y):
    rootX = find(parent, x)
    rootY = find(parent, y)
    if rootX != rootY:
        parent[rootX] = rootY

def kruskal(graph: List[List[int]], n: int) -> int:
    edges = []
    for u, v, w in graph:
        edges.append((w, u, v))
    edges.sort()
    parent = list(range(n))
    total_weight = 0
    for w, u, v in edges:
        if find(parent, u) != find(parent, v):
            union(parent, u, v)
            total_weight += w
    return total_weight if find(parent, 0) == find(parent, n - 1) else -1

