from collections import defaultdict

def game_winner(N, cards):
    # Create a graph where each node represents a card and edges represent possible moves
    graph = defaultdict(list)
    for i in range(N):
        for j in range(i + 1, N):
            if cards[i][0] == cards[j][0] or cards[i][1] == cards[j][1]:
                graph[i].append(j)
                graph[j].append(i)

    # Check if the graph is bipartite
    visited = [False] * N
    color = [0] * N

    def is_bipartite(node, c):
        visited[node] = True
        color[node] = c
        for neighbor in graph[node]:
            if not visited[neighbor]:
                if not is_bipartite(neighbor, 1 - c):
                    return False
            elif color[neighbor] == color[node]:
                return False
        return True

    for i in range(N):
        if not visited[i]:
            if not is_bipartite(i, 0):
                return "Aoki"

    return "Takahashi"

