        n = len(nums)
        if n == 1:
            return nums[0] * k

        max_strength = float('-inf')

        def dfs(start, current_strength, current_count):
            nonlocal max_strength
            if current_count == k:
                max_strength = max(max_strength, current_strength)
                return

            for i in range(start, n):
                if current_count == 0:
                    dfs(i + 1, nums[i], 1)
                else:
