        n = len(nums)
        ones = [i for i in range(n) if nums[i] == 1]

        if k == 1:
            return 1 if 1 in nums else 0

        min_moves = float('inf')

        for aliceIndex in range(n):
            if nums[aliceIndex] == 0:
                continue

            left = aliceIndex
            right = aliceIndex

            while right < n and nums[right] == 0:
                right += 1

            if right - left < k:
                continue

            ones_count = right - left
            moves = 0

            while ones_count < k:
                if left < n and nums[left] == 0:
                    if maxChanges > 0:
                        nums[left] = 1
                        maxChanges -= 1
                        moves += 1
                    else:
                        break
                left += 1
                ones_count += 1

            while ones_count > k:
                if right < n and nums[right] == 1:
                    nums[right] = 0
                    moves += 1
                    ones_count -= 1
                right -= 1

            if ones_count == k:
                min_moves = min(min_moves, moves)

        return min_moves

