class Solution:
    def minOperationsToMakeMedianK(self, nums: List[int], k: int) -> int:
        nums.sort()
        n = len(nums)
        left, right = 0, n - 1
        operations = 0

        while left <= right:
            mid = (left + right) // 2
            if nums[mid] == k:
                break
            elif nums[mid] < k:
                left = mid + 1
            else:
                right = mid - 1

        if nums[mid] == k:
            return 0

        if nums[mid] < k:
            for i in range(mid, n):
                operations += abs(nums[i] - k)
