        MOD = 10**9 + 7
        n = len(nums)
        nums.sort()

        def count_subsequences(i, current_sum):
            if current_sum == k:
                return 1
            if i == n or current_sum > k:
                return 0

            count = count_subsequences(i + 1, current_sum)  # Skip the current element
            count += count_subsequences(i + 1, current_sum + nums[i])  # Include the current element
            return count

        total_power = 0
        for i in range(n):
            total_power += count_subsequences(i + 1, nums[i]) * (2 ** i)
            total_power %= MOD

