class Solution:
    def waysToReachStair(self, k: int) -> int:
        @lru_cache(None)
        def dp(stair):
            if stair == 0:
                return 1
            if stair < 0:
                return 0
            ways = 0
            # Go down to stair i - 1
            ways += dp(stair - 1)
            # Go up to stair i + 2^jump
            jump = 0
            while stair + (1 << jump) <= k:
                ways += dp(stair + (1 << jump))
                jump += 1
            return ways

        return dp(k)

