def count_reachable_pairs(N, edges):
    # Create an adjacency list to represent the graph
    graph = [[] for _ in range(N + 1)]
    for u, v in edges:
        graph[u].append(v)

    # Initialize a list to keep track of the number of reachable vertices from each vertex
    reachable_count = [0] * (N + 1)

    # Perform a depth-first search to count reachable vertices
    def dfs(node):
        reachable_count[node] = 1
        for neighbor in graph[node]:
            if reachable_count[neighbor] == 0:
                dfs(neighbor)

    # Start DFS from each vertex
    for i in range(1, N + 1):
        if reachable_count[i] == 0:
            dfs(i)

    # Calculate the number of pairs (u, v) where v is reachable from u
    total_pairs = 0
    for i in range(1, N + 1):
        for j in range(1, N + 1):
            if reachable_count[i] >= reachable_count[j]:
                total_pairs += 1

    return total_pairs

