def is_connected(graph: List[List[int]], n: int) -> bool:
    visited = [False] * (n + 1)
    stack = [1]
    visited[1] = True

    while stack:
        node = stack.pop()
        for neighbor in graph[node]:
            if not visited[neighbor]:
                visited[neighbor] = True
                stack.append(neighbor)

    return all(visited)

def minimum_spanning_tree(graph: List[List[int]], n: int) -> int:
    edges = []
    for u in range(1, n + 1):
        for v in range(u + 1, n + 1):
            if graph[u][v] != 0:
                edges.append((graph[u][v], u, v))

    edges.sort()
    parent = list(range(n + 1))
    rank = [0] * (n + 1)

    def find(x: int) -> int:
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x: int, y: int) -> bool:
        rootX = find(x)
        rootY = find(y)
        if rootX == rootY:
            return False
        if rank[rootX] > rank[rootY]:
            parent[rootY] = rootX
        elif rank[rootX] < rank[rootY]:
            parent[rootX] = rootY
        else:
            parent[rootY] = rootX
            rank[rootX] += 1
        return True

    total_cost = 0
    for cost, u, v in edges:
        if union(u, v):
            total_cost += cost

    return total_cost

