class Solution:
    def minimumDifference(self, nums: List[int], k: int) -> int:
        if k == 1:
            return 0

        min_diff = float('inf')
        current_or = 0

        for i in range(len(nums)):
            current_or |= nums[i]
            if i >= k - 1:
                min_diff = min(min_diff, abs(k - current_or))
                current_or -= nums[i - (k - 1)]

        return min_diff

