class Solution:
    def minimumArea(self, grid: List[List[int]]) -> int:
        rows, cols = len(grid), len(grid[0])
        min_area = float('inf')

        for i in range(rows):
            for j in range(cols):
                if grid[i][j] == 1:
                    left = j
                    while left >= 0 and grid[i][left] == 1:
                        left -= 1
                    right = j
                    while right < cols and grid[i][right] == 1:
                        right += 1
                    top = i
                    while top >= 0 and grid[top][j] == 1:
                        top -= 1
                    bottom = i
                    while bottom < rows and grid[bottom][j] == 1:
                        bottom += 1

                    width = right - left - 1
                    height = bottom - top - 1
                    if width > 0 and height > 0:
                        min_area = min(min_area, width * height)

        return min_area if min_area != float('inf') else 0

