class Solution:
    def maxHeightOfTriangle(self, red: int, blue: int) -> int:
        if red == 0 and blue == 0:
            return 0

        # Initialize the maximum height for red and blue
        max_red_height = 0
        max_blue_height = 0

        # If there are more red balls, use them to form the triangle
        if red >= blue:
            max_red_height = red
            max_blue_height = (red + 1) // 2
        else:
            max_blue_height = blue
            max_red_height = (blue + 1) // 2

        # The maximum height of the triangle is the maximum of the two heights
        return max(max_red_height, max_blue_height)

