class Solution:
    def minimumCost(self, m: int, n: int, horizontalCut: List[int], verticalCut: List[int]) -> int:
        # Sort the cuts to find the maximum gaps
        horizontalCut.sort()
        verticalCut.sort()

        # Calculate the maximum gap between horizontal cuts
        max_horizontal_gap = max(horizontalCut[0], m - horizontalCut[-1])
        for i in range(1, len(horizontalCut)):
            max_horizontal_gap = max(max_horizontal_gap, horizontalCut[i] - horizontalCut[i - 1])

        # Calculate the maximum gap between vertical cuts
        max_vertical_gap = max(verticalCut[0], n - verticalCut[-1])
        for i in range(1, len(verticalCut)):
            max_vertical_gap = max(max_vertical_gap, verticalCut[i] - verticalCut[i - 1])

        # The total cost is the sum of the maximum gaps multiplied
        return (max_horizontal_gap * max_vertical_gap) % (10**9 + 7)

