class Solution:
    def nonSpecialCount(self, l: int, r: int) -> int:
        def is_special(n):
            divisors = [1]
            for i in range(2, int(n**0.5) + 1):
                if n % i == 0:
                    divisors.append(i)
                    if i != n // i:
                        divisors.append(n // i)
            return len(divisors) == 2

        count = 0
        for num in range(l, r + 1):
            if is_special(num):
                count += 1
        return r - l - count

