class Solution:
    def canReachCorner(self, xCorner: int, yCorner: int, circles: List[List[int]]) -> bool:
        import math

        def is_point_in_circle(x, y, circle):
            cx, cy, r = circle
            return (x - cx) ** 2 + (y - cy) ** 2 <= r ** 2

        def is_path_valid(x, y):
            if x == 0 and y == 0:
                return True
            if x == xCorner and y == yCorner:
                return True
            for circle in circles:
                if is_point_in_circle(x, y, circle):
                    return False
            return False

        def dfs(x, y):
            if x == xCorner and y == yCorner:
                return True
            if x < 0 or y < 0 or x > xCorner or y > yCorner:
                return False
            if is_path_valid(x, y):
                return dfs(x + 1, y) or dfs(x, y + 1)
            return False

        return dfs(0, 0)

