class Solution:
    def numberOfPermutations(self, n: int, requirements: List[List[int]]) -> int:
        MOD = 10**9 + 7

        # Helper function to count inversions in a subarray
        def count_inversions(arr):
            inversions = 0
            for i in range(len(arr)):
                for j in range(i + 1, len(arr)):
                    if arr[i] > arr[j]:
                        inversions += 1
            return inversions

        # Helper function to generate permutations and check inversions
        def generate_permutations(start, current_perm):
            if start == n:
                if all(count_inversions(current_perm[:end + 1]) == cnt for end, cnt in requirements):
                    return 1
                return 0
            total = 0
            for i in range(n):
                if i not in current_perm:
                    current_perm.append(i)
                    total += generate_permutations(start + 1, current_perm)
                    current_perm.pop()
            return total % MOD

        return generate_permutations(0, [])

