    def minChanges(self, nums: List[int], k: int) -> int:
        n = len(nums)
        count = [0] * k
        freq = [0] * (k + 1)
        changes = [0] * k

        for i in range(n):
            index = i % k
            changes[index] += 1
            freq[nums[i]] += 1

            min_changes = float('inf')
            for j in range(k):
                min_changes = min(min_changes, freq[j] - count[j])

            for j in range(k):
                count[j] += freq[j]
