class Solution:
    def minFlips(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        def is_palindromic(row):
            return row == row[::-1]

        def flip_row(row):
            return [1 - x for x in row]

        def flip_column(col):
            return [grid[i][col] for i in range(m)]

        def count_flips(row):
            flips = 0
            for i in range(n // 2):
                if row[i] != row[n - 1 - i]:
                    flips += 1
            return flips

        def count_flips_col(col):
            flips = 0
            for i in range(m // 2):
                if grid[i][col] != grid[m - 1 - i][col]:
                    flips += 1
            return flips

        min_flips = float('inf')

        for i in range(m):
            if not is_palindromic(grid[i]):
                flips = count_flips(grid[i])
                min_flips = min(min_flips, flips)

        for j in range(n):
            if not is_palindromic([grid[i][j] for i in range(m)]):
                flips = count_flips_col(j)
                min_flips = min(min_flips, flips)

        return min_flips

