def is_valid_sequence(sequence, R, K):
    if sum(sequence) % K != 0:
        return False
    for i in range(len(sequence)):
        if sequence[i] < 1 or sequence[i] > R[i]:
            return False
    return True

def generate_sequences(N, K, R):
    sequences = []
    def backtrack(current_sequence, index):
        if index == N:
            if is_valid_sequence(current_sequence, R, K):
                sequences.append(current_sequence[:])
            return
        for i in range(1, R[index] + 1):
            current_sequence.append(i)
            backtrack(current_sequence, index + 1)
            current_sequence.pop()
    backtrack([], 0)
    return sequences

