def min_lexicographical_operations(S: str, T: str) -> List[str]:
    if S == T:
        return [S]

    operations = []
    while S != T:
        min_diff_index = -1
        min_diff_char = None

        for i in range(len(S)):
            if S[i] != T[i]:
                if min_diff_char is None or S[i] < min_diff_char:
                    min_diff_index = i
                    min_diff_char = S[i]

        if min_diff_index == -1:
            break

        S = S[:min_diff_index] + T[min_diff_index] + S[min_diff_index+1:]
        operations.append(S)

    return operations

