def process_queries(H, W, Q, queries):
    grid = [[1 for _ in range(W)] for _ in range(H)]
    remaining_walls = H * W

    for R_q, C_q in queries:
        R_q -= 1
        C_q -= 1

        if grid[R_q][C_q] == 1:
            grid[R_q][C_q] = 0
            remaining_walls -= 1
        else:
            # Destroy walls in the four directions
            for i in range(R_q - 1, -1, -1):
                if grid[i][C_q] == 1:
                    grid[i][C_q] = 0
                    remaining_walls -= 1
                else:
                    break
            for i in range(R_q + 1, H):
                if grid[i][C_q] == 1:
                    grid[i][C_q] = 0
                    remaining_walls -= 1
                else:
                    break
            for j in range(C_q - 1, -1, -1):
                if grid[R_q][j] == 1:
                    grid[R_q][j] = 0
                    remaining_walls -= 1
                else:
                    break
            for j in range(C_q + 1, W):
                if grid[R_q][j] == 1:
                    grid[R_q][j] = 0
                    remaining_walls -= 1
                else:
                    break

    return remaining_walls

