def max_min_weight(N: int, K: int, A: List[int]) -> Tuple[int, int]:
    total_mass = sum(A)
    min_weight = total_mass // K
    max_weight = total_mass // K + (1 if total_mass % K != 0 else 0)

    # Try to find the minimum possible weight
    for i in range(min_weight, max_weight + 1):
        if total_mass % i == 0:
            min_weight = i
            break

    # Check if it's possible to divide the cake into K parts with min_weight
    if min_weight * K < total_mass:
        return (min_weight, 0)

    # Try to find the number of cut lines that are never cut
    never_cut = 0
    for i in range(1, N + 1):
        if A[i - 1] >= min_weight:
            never_cut += 1

    return (min_weight, never_cut)

