def is_isomorphic(G, H, A):
    N = len(G)
    G_edges = set()
    H_edges = set()

    for u, v in G:
        G_edges.add((u, v))

    for u, v in H:
        H_edges.add((u, v))

    if G_edges != H_edges:
        return float('inf')

    for perm in permutations(range(1, N + 1)):
        if all((perm[u - 1], perm[v - 1]) in H_edges for u, v in G):
            return sum(A[i][j] for i in range(1, N) for j in range(i + 1, N) if (perm[i - 1], perm[j - 1]) not in H_edges)

    return float('inf')

