def can_make_equal(A, B, M):
    if A == B:
        return 0

    operations = 0
    for i in range(len(A)):
        if A[i] != B[i]:
            diff = (B[i] - A[i]) % M
            if diff == 0:
                diff = M
            if diff > M // 2:
                diff = M - diff
            operations += diff

    return operations if operations <= len(A) else -1

