def can_make_identical(A, B, K):
    if len(A) != len(B):
        return "No"

    for i in range(len(A)):
        if A[i] != B[i]:
            for j in range(max(0, i - K), min(len(A), i + K + 1)):
                if A[j] == B[i]:
                    A[i] = B[i]
                    break
            else:
                return "No"

    return "Yes"

