def count_valid_permutations(N: int, M: List[List[int]]) -> int:
    MOD = 998244353

    def is_valid_permutation(perm: List[int]) -> bool:
        for l, r, x in M:
            max_val = float('-inf')
            for i in range(l - 1, r):
                if perm[i] > max_val:
                    max_val = perm[i]
