class Solution:
    def maxPathLength(self, coordinates: List[List[int]], k: int) -> int:
        n = len(coordinates)
        directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]

        # Helper function to check if a point is within bounds
        def is_valid(x, y):
            return 0 <= x < n and 0 <= y < n

        # Helper function to find the maximum path length starting from a given point
        def dfs(x, y, visited):
            if (x, y) in visited:
                return visited[(x, y)]

            max_length = 1
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if is_valid(nx, ny) and coordinates[nx][ny] > coordinates[x][y]:
                    max_length = max(max_length, 1 + dfs(nx, ny, visited))

            visited[(x, y)] = max_length
            return max_length

        max_path = 0
        for i in range(n):
            if i == k:
                max_path = max(max_path, dfs(i, 0, {}))

        return max_path

