def can_make_equal_strength(N: int, A: List[int], B: List[int]) -> int:
    total_strength = sum(B)
    if total_strength % 3 != 0:
        return -1

    target_strength = total_strength // 3

    team_strengths = [0, 0, 0]
    for i in range(N):
        team_strengths[A[i] - 1] += B[i]

    if any(strength != target_strength for strength in team_strengths):
        return -1

    switches = 0
    for i in range(N):
        if A[i] != 1:
            switches += 1

    return switches

