def min_moves_to_tile(K, S_x, S_y, T_x, T_y):
    def is_even(n):
        return n % 2 == 0

    def get_tile(i, j, k):
        if is_even(i) == is_even(j):
            return (i * K, j * K + k, i * K + (j + 1) * K, j * K + k + 1)
        else:
            return (i * K + k, j * K, i * K + k + 1, j * K + (j + 1) * K)

    def is_adjacent(tile1, tile2):
        x1, y1, x2, y2 = tile1
        x3, y3, x4, y4 = tile2
        return (x1 <= x3 <= x2 and y1 <= y3 <= y2) or (x1 <= x4 <= x2 and y1 <= y4 <= y2) or (x3 <= x1 <= x4 and y3 <= y1 <= y4) or (x3 <= x2 <= x4 and y3 <= y2 <= y4)

    def get_distance(tile1, tile2):
        x1, y1, x2, y2 = tile1
        x3, y3, x4, y4 = tile2
        return abs(x1 - x3) + abs(y1 - y3)

    def bfs(start_tile, target_tile):
        queue = [(start_tile, 0)]
        visited = set([start_tile])

        while queue:
            current_tile, moves = queue.pop(0)
            if current_tile == target_tile:
                return moves

            for dx in [-1, 1]:
                for dy in [-1, 1]:
                    new_tile = (current_tile[0] + dx, current_tile[1] + dy, current_tile[2] + dx, current_tile[3] + dy)
                    if new_tile not in visited and is_adjacent(current_tile, new_tile):
                        visited.add(new_tile)
                        queue.append((new_tile, moves + 1))

        return -1  # If no path is found

    start_tile = get_tile(int(S_x / K), int(S_y / K), int(S_x % K))
    target_tile = get_tile(int(T_x / K), int(T_y / K), int(T_x % K))

    return bfs(start_tile, target_tile)

