def f(A):
    n = len(A)
    graph = defaultdict(list)
    for i in range(n):
        for j in range(i + 1, n):
            if A[i] <= A[j]:
                graph[i].append(j)
                graph[j].append(i)
    visited = [False] * n
    components = 0
    for i in range(n):
        if not visited[i]:
            components += 1
            stack = [i]
            while stack:
                node = stack.pop()
                if not visited[node]:
                    visited[node] = True
                    for neighbor in graph[node]:
                        stack.append(neighbor)
    return components

