class Solution:
    def maxScore(self, nums: List[int]) -> int:
        n = len(nums)

        def gcd(a, b):
            while b:
                a, b = b, a % b
            return a

        def lcm(a, b):
            return abs(a * b) // gcd(a, b)

        def factor_score(arr):
            if not arr:
                return 0
            result = arr[0]
            for num in arr[1:]:
                result = lcm(result, num)
            return result * gcd(*arr)

        max_score = 0

        for i in range(n):
            remaining = nums[:i] + nums[i+1:]
            max_score = max(max_score, factor_score(remaining))

        return max_score

