class Solution:
    def minTimeToReach(self, moveTime: List[List[int]]) -> int:
        n, m = len(moveTime), len(moveTime[0])
        queue = [(0, 0, 0)]  # (time, x, y)
        visited = set()

        while queue:
            time, x, y = queue.pop(0)

            if (x, y) == (n - 1, m - 1):
                return time

            for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < m and (nx, ny) not in visited:
