class Solution:
    def countBalancedPermutations(self, num: str) -> int:
        MOD = 10**9 + 7

        # Count the frequency of each digit
        digit_count = Counter(num)
        zero_count = digit_count['0']

        # If there's more than one '0', it's impossible to form a balanced permutation
        if zero_count > 1:
            return 0

        # If there's only one '0', we need to place it in the middle
        if zero_count == 1:
            odd_count = sum(1 for d in num if d != '0')
            if odd_count % 2 == 0:
                return 1
            else:
                return 0

        # If there are no '0's, we need to find the number of balanced permutations
        odd_count = sum(1 for d in num if d != '0')
        if odd_count % 2 != 0:
            return 0

        # Calculate the number of balanced permutations
        total_permutations = 1
        for count in digit_count.values():
            if count > 1:
                total_permutations *= self.factorial(count)
                total_permutations %= MOD

        return total_permutations % MOD

    def factorial(self, n: int) -> int:
        result = 1
        for i in range(2, n + 1):
            result *= i
            result %= 10**9 + 7
        return result

