class Solution:
    def maximizeSumOfWeights(self, edges: List[List[int]], k: int) -> int:
        n = len(edges) + 1
        graph = [[] for _ in range(n)]

        for u, v, w in edges:
            graph[u].append((v, w))
            graph[v].append((u, w))

        def dfs(node, parent):
            total_weight = 0
            max_edges = []
            for neighbor, weight in graph[node]:
                if neighbor != parent:
                    child_weight, child_edges = dfs(neighbor, node)
                    total_weight += child_weight
                    heapq.heappush(max_edges, -child_edges)
                    if len(max_edges) > k:
                        heapq.heappop(max_edges)
            max_edges = [-edge for edge in max_edges]
            return total_weight + sum(max_edges), len(max_edges) + 1

        _, _ = dfs(0, -1)
        return -sum(max_edges) + sum(weight for u, v, weight in edges)

