class Solution:
    def maxCollectedFruits(self, fruits: List[List[int]]) -> int:
        n = len(fruits)
        max_fruits = 0

        # Child starting from (0, 0)
        for i in range(n):
            for j in range(n):
                current_fruits = 0
                x, y = 0, 0
                while x < n and y < n:
                    current_fruits += fruits[x][y]
                    x += 1
                    y += 1
                max_fruits = max(max_fruits, current_fruits)

        # Child starting from (0, n-1)
        for i in range(n):
            for j in range(n-1, -1, -1):
                current_fruits = 0
                x, y = 0, j
                while x < n and y >= 0:
                    current_fruits += fruits[x][y]
                    x += 1
                    y -= 1
                max_fruits = max(max_fruits, current_fruits)

        # Child starting from (n-1, 0)
        for i in range(n-1, -1, -1):
            for j in range(n):
                current_fruits = 0
                x, y = i, 0
                while x >= 0 and y < n:
                    current_fruits += fruits[x][y]
                    x -= 1
                    y += 1
                max_fruits = max(max_fruits, current_fruits)

        return max_fruits

