class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        prefix_sum = 0
        max_sum = float('-inf')
        remainder_sum = [0] * k
        remainder_sum[0] = 0

        for i in range(len(nums)):
            prefix_sum += nums[i]
            remainder = prefix_sum % k

            if remainder == 0:
                max_sum = max(max_sum, prefix_sum)
            else:
                max_sum = max(max_sum, prefix_sum - remainder_sum[remainder])

            remainder_sum[remainder] = max(remainder_sum[remainder], prefix_sum)

        return max_sum

