class Solution:
    def minOperations(self, n: int, m: int) -> int:
        if n == m:
            return 0

        def is_prime(num):
            if num <= 1:
                return False
            if num <= 3:
                return True
            if num % 2 == 0 or num % 3 == 0:
                return False
            i = 5
            while i * i <= num:
                if num % i == 0 or num % (i + 2) == 0:
                    return False
                i += 6
            return True

        min_cost = float('inf')

        for i in range(10000):
            current_n = n
            cost = 0
            while current_n != m:
                if is_prime(current_n):
                    break
                if current_n < m:
                    if current_n % 10 != 9:
                        current_n += 1
                    else:
                        current_n = int(str(current_n)[:-1]) + 1
                else:
                    if current_n % 10 != 0:
                        current_n -= 1
                    else:
                        current_n = int(str(current_n)[:-1]) - 1
                cost += current_n
            if current_n == m and cost < min_cost:
                min_cost = cost

        return min_cost if min_cost != float('inf') else -1

