class Solution:
    def maxAmount(self, initialCurrency: str, pairs1: List[List[str]], rates1: List[float], pairs2: List[List[str]], rates2: List[float]) -> float:
        def convert(start, target, rates):
            if start == target:
                return 1.0
            for i in range(len(rates)):
                if rates[i][0] == start and rates[i][1] == target:
                    return rates[i][2]
            return 1.0

        def dfs(start, target, day, memo):
            if (start, target, day) in memo:
                return memo[(start, target, day)]
            if day == 1:
                rate = convert(start, target, pairs1)
            else:
                rate = convert(start, target, pairs2)
            memo[(start, target, day)] = rate * dfs(target, initialCurrency, day + 1, memo)
            return memo[(start, target, day)]

        memo = {}
        max_amount = 0.0
        for i in range(1, 3):
            max_amount = max(max_amount, dfs(initialCurrency, initialCurrency, i, memo))
        return max_amount

