        unique_elements = set(nums)

        for num in unique_elements:
            if count[num] > 1:
                for i in range(1, count[num]):
                    if num - k >= 0 and num - k in count:
                        count[num - k] += 1
                        count[num] -= 1
                    elif num + k <= 10**9 and num + k in count:
