class Solution:
    def answerString(self, word: str, numFriends: int) -> str:
        def is_valid_split(splits):
            return len(splits) == numFriends and all(len(split) > 0 for split in splits)

        def get_lexicographically_largest(splits):
            return ''.join(sorted(splits, reverse=True))

        def backtrack(start, splits):
            if is_valid_split(splits):
                return get_lexicographically_largest(splits)

            largest_split = ''
            for i in range(start, len(word)):
                splits.append(word[start:i+1])
                result = backtrack(i + 1, splits)
                if result:
                    largest_split = result
                splits.pop()

            return largest_split

        return backtrack(0, [])

