class Solution:
    def countGoodArrays(self, n: int, m: int, k: int) -> int:
        MOD = 10**9 + 7

        @lru_cache(None)
        def count_good_arrays(i, prev, count):
            if i == n:
                return 1 if count == k else 0

            total = 0
            for num in range(1, m + 1):
                if num == prev:
                    total += count_good_arrays(i + 1, num, count)
                else:
                    total += count_good_arrays(i + 1, num, count + 1)

            return total % MOD

        return count_good_arrays(0, 0, 0)

