class Solution:
    def countPathsWithXorValue(self, grid: List[List[int]], k: int) -> int:
        m, n = len(grid), len(grid[0])
        MOD = 10**9 + 7

        # Initialize DP table
        dp = [[0] * n for _ in range(m)]
        dp[0][0] = grid[0][0] % MOD

        # Directions for moving right or down
        directions = [(0, 1), (1, 0)]

        for i in range(m):
            for j in range(n):
                for dx, dy in directions:
                    x, y = i + dx, j + dy
                    if 0 <= x < m and 0 <= y < n:
                        dp[x][y] = (dp[x][y] + dp[i][j]) % MOD
                        dp[x][y] = (dp[x][y] + grid[x][y] * pow(2, i * n + j, MOD)) % MOD

        return dp[m - 1][n - 1] if dp[m - 1][n - 1] % MOD == k else 0

