class Solution:
    def checkValidCuts(self, n: int, rectangles: List[List[int]]) -> bool:
        # Calculate the area of each rectangle
        areas = set()
        for x1, y1, x2, y2 in rectangles:
            area = (x2 - x1) * (y2 - y1)
            areas.add(area)

        # Check if we can make two horizontal cuts
        horizontal_cuts = 0
        for y1, y2 in sorted([(y1, y2) for x1, y1, x2, y2 in rectangles]):
            if y2 - y1 > 1:
                horizontal_cuts += 1

        # Check if we can make two vertical cuts
        vertical_cuts = 0
        for x1, x2 in sorted([(x1, x2) for x1, y1, x2, y2 in rectangles]):
            if x2 - x1 > 1:
                vertical_cuts += 1

        # If we can make at least two cuts in either direction, return true
        return horizontal_cuts >= 2 or vertical_cuts >= 2

