class Solution:
    def maxLength(self, nums: List[int]) -> int:
        max_length = 0

        for i in range(len(nums)):
            product = 1
            gcd_value = nums[i]
            lcm_value = nums[i]

            for j in range(i, len(nums)):
                product *= nums[j]
                gcd_value = math.gcd(gcd_value, nums[j])
                lcm_value = (lcm_value * nums[j]) // math.gcd(lcm_value, nums[j])

                if product == lcm_value * gcd_value:
                    max_length = max(max_length, j - i + 1)

