class Solution:
    def maximumCoins(self, coins: List[List[int]], k: int) -> int:
        n = len(coins)
        dp = [[0] * (k + 1) for _ in range(n + 1)]

        for i in range(1, n + 1):
            l, r, c = coins[i - 1]
            for j in range(1, k + 1):
                dp[i][j] = dp[i - 1][j]
                if l <= j:
                    dp[i][j] = max(dp[i][j], dp[i - 1][j - l] + c * (j - l + 1))

